python3 -c "
import csv;r=list(csv.DictReader(open('calc_r3/szl_cf_hist.csv')))
from collections import defaultdict;y=defaultdict(lambda:[0,0,0])
for x in r:
  k=x['quarter'][:4];y[k][0]+=float(x['NP_P0'])/1e9;y[k][1]+=float(x['CF_OA_P0'])/1e9;y[k][2]+=float(x['CF_Invest_P0'])/1e9
for k in sorted(y):print(k,[round(v,1) for v in y[k]])"
cd ../calc_b && sed -e 's/^NCS = (0.20, 0.10, 0.0)/NCS = (0.0, 0.0, 0.0)/' -e "s#json.dump(OUT.*##" model_rev4b.py > /tmp/szl_nc0.py && grep -n "^NCS" /tmp/szl_nc0.py && cp /tmp/szl_nc0.py ./_skeptic_nc0_tmp.py && /home/trido/thanhdt/wc_venv/bin/python -I _skeptic_nc0_tmp.py | grep HEADLINE; rm -f _skeptic_nc0_tmp.py

